      en: "The unit joint-rate sphere maps to the ellipsoid q̇ᵀ(JJᵀ)⁻¹q̇ = 1; semi-axes √λᵢ, volume ∝ √det(JJᵀ); µ1, µ2 (condition number of A), µ3 = √det A; the force ellipsoid uses (JJᵀ)⁻¹. PDF body verified with pdftotext; 以原文为准.",
